head.script:
scwin.onpageunload = function() {};
scwin.btnPop_onclick = function(e) {
    var options = {
        id: "popup1",
        type: "wframePopup",
        width: "230px",
        height: "150px",
        top: "130px",
        left: "200px",
        popupName: "openPopup1",
        modal: true,
        useModalStack: true,
        alwaysOnTop: false,
        resizable: true,
        status: true,
        menubar: false,
        scrollbars: false,
        title: false,
        closeAction: "scwin.callback"
    };
    scwin.$w.openPopup("popup_select_WEFF-286_(WSQ-3552)_sub.xml", options);
};
scwin.onpageload = function() {
    if(WebSquare._xv !== "SP5"){requires("uiplugin.popup");}
}
